@Override public void handle(RoutingContext context){
  if (ignoreContext(context)) {
    context.next();
    return;
  }
  try {
    executor.execute(createBlockingHandler(context));
  } catch (RejectedExecutionException e) {
    // 处理线程池拒绝执行的情况，如记录日志或执行降级策略
    Thread.currentThread().getThreadGroup().getParent().uncaughtException(Thread.currentThread(), e);
  }
}
